  p jsonb; pid uuid;
begin
  for p in select * from jsonb_array_elements(doc) loop
    insert into public.playlists (company_id, kind, title, purpose, status, spotify_playlist_id, artwork_url, synced_at, sync_truncated, created_by)
    values (c, 'editorial', left(p->>'name', 120), case when p->>'name' ~* '(חופה|hupa|chupp?ah)' then 'ceremony' end, 'published', p->>'id', null, now(), (p->>'n')::int >= 100, adm)
    on conflict (company_id, spotify_playlist_id) do update set artwork_url = excluded.artwork_url, synced_at = now(), sync_truncated = excluded.sync_truncated
    returning id into pid;
    insert into public.artists (company_id, name) select distinct c, x->>2 from jsonb_array_elements(p->'t') x on conflict (company_id, name) do nothing;
    insert into public.music_tracks (company_id, title, artist_id, provider, provider_track_id, external_url, rights_status, status)
    select c, x->>1, ar.id, 'spotify', x->>0, 'https://open.spotify.com/track/' || (x->>0), 'metadata_only', 'published'
    from jsonb_array_elements(p->'t') x join public.artists ar on ar.company_id = c and ar.name = x->>2
    on conflict (company_id, provider, provider_track_id) do nothing;
    delete from public.playlist_tracks where playlist_id = pid;
    insert into public.playlist_tracks (playlist_id, track_id, position)
    select pid, mt.id, (o - 1)::int from jsonb_array_elements(p->'t') with ordinality as e(x, o)
    join public.music_tracks mt on mt.company_id = c and mt.provider = 'spotify' and mt.provider_track_id = x->>0;
  end loop;
end $do$;